import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, Object3D } = ctx.THREE;

  const root = new Group();
  root.name = 'stat-tile-home';
  root.position.set(-2.5, 1.6, 0);

  let gltfLoaded = false;
  let primitiveCleanups = [];
  let gsapTimelines = [];
  const handlers = {};

  // Load GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    gltfLoaded = true;
    const scene = gltf.scene;

    // Traverse and ensure proper materials
    scene.traverse((node) => {
      if (node.isMesh) {
        // Preserve GLB materials; ensure they're node-based
        if (!node.material.isNodeMaterial) {
          const originalMat = node.material;
          const newMat = new MeshStandardNodeMaterial({
            color: originalMat.color || 0xffffff,
            metalness: originalMat.metalness ?? 0.8,
            roughness: originalMat.roughness ?? 0.4,
            map: originalMat.map,
            normalMap: originalMat.normalMap,
            roughnessMap: originalMat.roughnessMap,
            metalnessMap: originalMat.metalnessMap,
          });
          node.material = newMat;
        }
        node.castShadow = true;
        node.receiveShadow = true;
      }
    });

    root.add(scene);
  });

  // Hover effect: rise-in (subtle 0.15 scene units)
  handlers.onPointerEnter = () => {
    if (!gltfLoaded) return;

    // Kill any active timeline for this action
    gsapTimelines.forEach(tl => {
      if (tl._id === 'hover-rise') tl.kill();
    });

    const tl = gsap.timeline({ id: 'hover-rise' });
    tl.to(root.position, {
      y: root.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsapTimelines.push(tl);
  };

  handlers.onPointerLeave = () => {
    if (!gltfLoaded) return;

    const tl = gsap.timeline();
    tl.to(root.position, {
      y: 1.6,
      duration: 0.9,
      ease: 'power4.out',
      overwrite: 'auto',
    });
    gsapTimelines.push(tl);
  };

  // Click: press-down scale effect + emit event
  handlers.onClick = () => {
    if (!gltfLoaded) return;

    gsapTimelines.forEach(tl => {
      if (tl._id === 'press-down') tl.kill();
    });

    const tl = gsap.timeline({ id: 'press-down' });
    tl.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
    }, 0);
    tl.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.3,
      ease: 'back.out',
    });
    gsapTimelines.push(tl);

    // Emit navigation event
    ctx.emit('hub-home.select', { tile: 'stat' });
  };

  root.userData = {
    handlers,
    cleanup: () => {
      // Kill all GSAP timelines
      gsapTimelines.forEach(tl => tl.kill());
      gsapTimelines = [];

      // Clean up primitives
      primitiveCleanups.forEach(cleanup => cleanup?.());
      primitiveCleanups = [];

      // Dispose geometries and materials
      root.traverse((node) => {
        if (node.isMesh) {
          node.geometry?.dispose();
          if (Array.isArray(node.material)) {
            node.material.forEach(m => m.dispose?.());
          } else {
            node.material?.dispose?.();
          }
        }
      });
    },
  };

  // Apply parallax-scroll cinematic primitive
  if (config.cinematicPrimitives?.length > 0) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (primitive.name === 'parallax-scroll' && primitive.trigger === 'scroll') {
        const result = ctx.primitives['parallax-scroll'](root, primitive.params || { intensity: 0.25 });
        if (result?.cleanup) {
          primitiveCleanups.push(result.cleanup);
        }
      }
    });
  }

  return root;
}
